solution:
static class Inventory {
    private final String[] items;

    Inventory(String[] items) {
        this.items = items.clone();
    }

    String[] getItems() {
        return items.clone();
    }

    int size() {
        return items.length;
    }

    String first() {
        return items[0];
    }
}
